import 'package:equatable/equatable.dart'; import 'package:flutter_bloc/flutter_bloc.dart'; import '../../domain/entities/teacher_attendance_entity.dart'; import '../../domain/repositories/teacher_attendance_repository.dart';
sealed class TeacherAttendanceEvent extends Equatable { const TeacherAttendanceEvent(); @override List<Object?> get props=>[]; } class LoadTeacherAttendance extends TeacherAttendanceEvent { const LoadTeacherAttendance(this.date); final DateTime date; @override List<Object> get props=>[date]; } class SaveTeacherAttendance extends TeacherAttendanceEvent { const SaveTeacherAttendance(this.records,this.date); final List<TeacherAttendanceEntity> records; final DateTime date; @override List<Object> get props=>[records,date]; }
sealed class TeacherAttendanceState extends Equatable { const TeacherAttendanceState(); @override List<Object?> get props=>[]; } class TeacherAttendanceInitial extends TeacherAttendanceState { const TeacherAttendanceInitial(); } class TeacherAttendanceLoading extends TeacherAttendanceState { const TeacherAttendanceLoading(); } class TeacherAttendanceLoaded extends TeacherAttendanceState { const TeacherAttendanceLoaded(this.records); final List<TeacherAttendanceEntity> records; @override List<Object> get props=>[records]; } class TeacherAttendanceError extends TeacherAttendanceState { const TeacherAttendanceError(this.message); final String message; @override List<Object> get props=>[message]; }
class TeacherAttendanceBloc extends Bloc<TeacherAttendanceEvent,TeacherAttendanceState>{ TeacherAttendanceBloc(this._repository):super(const TeacherAttendanceInitial()){on<LoadTeacherAttendance>(_load);on<SaveTeacherAttendance>(_save);} final TeacherAttendanceRepository _repository; Future<void> _load(LoadTeacherAttendance e,Emitter<TeacherAttendanceState> emit)async{emit(const TeacherAttendanceLoading());try{emit(TeacherAttendanceLoaded(await _repository.getByDate(e.date)));}catch(error){emit(TeacherAttendanceError(error.toString()));}} Future<void> _save(SaveTeacherAttendance e,Emitter<TeacherAttendanceState> emit)async{emit(const TeacherAttendanceLoading());try{for(final record in e.records){await _repository.save(record);}emit(TeacherAttendanceLoaded(await _repository.getByDate(e.date)));}catch(error){emit(TeacherAttendanceError(error.toString()));}}}
